    VXPortalUser dbVXPortalUser = userMgr.deactivateUser(null);
    Assert.assertNull(dbVXPortalUser);
    dbVXPortalUser = userMgr.deactivateUser(user);
    Assert.assertNotNull(dbVXPortalUser);
